B.c1c=new A.af("Pentobarbital coma",null,B.ni,null,null,null,null,null,null,null,null)
B.c3o=new A.af("10 mg/kg load, then infusion at 1\u20136 mg/kg/hour",null,null,null,null,null,null,null,null,null,null)
B.c0r=new A.af("Spinal cord injury",null,B.ni,null,null,null,null,null,null,null,null)
B.c0F=new A.af("Consider Solumedrol: 30 mg/kg, then 5.4 mg/kg/hr for 23 h",null,null,null,null,null,null,null,null,null,null)
